// カテゴリ別に分け、各施策の主KPIだけ抽出
const rows = $input.all().map(i => i.json);
const KPIS = {
  A: r => ({ main: '新規参加者', value: r.entries_24h, sub: `imp=${r.imps} prof=${r.profile_clicks}` }),
  B: r => ({ main: '保存', value: r.saves, sub: `prof=${r.profile_clicks} dl=${r.dls}` }),
  C: r => ({ main: 'CV', value: r.purchases + r.line_adds, sub: `dm=${r.dms} rev=¥${Number(r.revenue).toLocaleString()}` }),
  D: r => ({ main: 'imp', value: r.imps, sub: `entries=${r.entries_24h} prof=${r.profile_clicks}` }),
};
const lines = ['*📊 24hキャンペーンKPI*'];
for (const cat of ['A','B','C','D']) {
  const rs = rows.filter(r => r.category === cat);
  if (rs.length === 0) continue;
  lines.push(`\n*— カテゴリ ${cat} —*`);
  for (const r of rs) {
    const kpi = KPIS[cat](r);
    lines.push(`• \`${r.type}\` *${r.title || r.id}*: ${kpi.main}=*${kpi.value}*  _${kpi.sub}_`);
  }
}
return [{ json: { text: lines.join('\n') } }];
